struct Parser<'a> { toks: &'a [Token], pos: usize }
impl Parser<'_> {
    fn bump(&mut self) -> &Token { let t = &self.toks[self.pos]; self.pos += 1; t }
    fn expr(&mut self) -> Result<Node, ParseError> {
        let mut left = self.term()?;                       // ? propagates positioned errors
        while matches!(self.toks[self.pos].kind, Kind::Plus | Kind::Minus) {  // loop, not left recursion
            let op = self.bump().kind;
            left = Node::Binary(Box::new(left), op, Box::new(self.term()?));
        }
        Ok(left)
    }
}

