use nom::{IResult, Parser, bytes::complete::tag, branch::alt, combinator::opt, multi::many0};

fn sign(i: &str) -> IResult<&str, Option<&str>> {
    opt(alt((tag("+"), tag("-")))).parse(i)
}
fn integer(i: &str) -> IResult<&str, i64> {
    let (rest, _) = sign(i)?;
    let (rest, digits) = nom::character::complete::digit1(rest)?;
    Ok((rest, digits.parse().unwrap()))
}

